/**
 * The compile-and-run engine.
 *
 * It compiles a Java source with the local JDK and runs it against an input,
 * then compares the result with an expected output. Everything runs in a private
 * temporary directory that is removed afterwards.
 *
 * The comparison is *differential* when possible: the reference solution for the
 * problem (generated by `scripts/generate-data.mjs`) is run on the same input,
 * so a wrong answer is detected even for inputs that have no recorded expected
 * output.
 */

import { mkdtempSync, writeFileSync, rmSync, readFileSync, existsSync, readdirSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { spawn, spawnSync } from 'node:child_process'

/* -------------------------------------------------------------------------- */
/* JDK discovery                                                               */
/* -------------------------------------------------------------------------- */

/**
 * Where JDKs usually live on Windows. A machine often has a `JAVA_HOME` that
 * points at a JDK which was uninstalled, so the usual install locations are
 * searched as well.
 */
const JDK_ROOTS = [
  'C:\\Program Files\\Eclipse Adoptium',
  'C:\\Program Files\\Java',
  'C:\\Program Files\\Microsoft',
  'C:\\Program Files\\Zulu',
  'C:\\Program Files\\Amazon Corretto',
  'C:\\Program Files\\BellSoft',
  'C:\\Program Files\\Oracle',
]

let cachedJdk = null

/** Finds a usable `javac`, or null when there is none. */
export function findJdk() {
  if (cachedJdk) return cachedJdk

  const candidates = []
  const push = (dir) => {
    if (!dir) return
    candidates.push(join(dir, 'bin', 'javac.exe'), join(dir, 'bin', 'javac'))
  }

  push(process.env.JAVA_HOME)

  for (const root of JDK_ROOTS) {
    try {
      for (const entry of readdirSync(root, { withFileTypes: true })) {
        if (entry.isDirectory()) push(join(root, entry.name))
      }
    } catch {
      // The directory does not exist — that is fine.
    }
  }

  candidates.push('javac')

  for (const candidate of candidates) {
    const probe = spawnSync(candidate, ['-version'], { encoding: 'utf8' })
    if (!probe.error && probe.status === 0) {
      cachedJdk = { javac: candidate, java: javaFor(candidate) }
      return cachedJdk
    }
  }
  return null
}

/** The `java` launcher that sits next to a given `javac`. */
function javaFor(javac) {
  const separator = javac.includes('\\') ? '\\' : '/'
  const candidate = javac.replace(
    /[\\/]javac(\.exe)?$/i,
    `${separator}java${javac.endsWith('.exe') ? '.exe' : ''}`,
  )
  const probe = spawnSync(candidate, ['-version'], { encoding: 'utf8' })
  if (!probe.error && probe.status === 0) return candidate
  return 'java'
}

/** The version string of the JDK in use, for the health endpoint. */
export function javaVersion() {
  const jdk = findJdk()
  if (!jdk) return null
  const probe = spawnSync(jdk.java, ['-version'], { encoding: 'utf8' })
  const line = (probe.stderr || probe.stdout || '').split('\n')[0]
  return line.trim() || null
}

export const LIMITS = {
  /** Maximum size of a submitted source file. */
  maxSourceBytes: 200 * 1024,
  /** Maximum time a single `javac` invocation may take. */
  compileTimeoutMs: 15_000,
  /** Maximum time a single program run may take. */
  runTimeoutMs: 8_000,
  /** Heap cap for the child JVM. */
  memoryMb: 256,
  /** Maximum captured stdout/stderr, in characters. */
  maxOutputChars: 200_000,
  /** How many runs may be in flight at once. */
  maxConcurrent: 4,
}

/* -------------------------------------------------------------------------- */
/* Concurrency                                                                 */
/* -------------------------------------------------------------------------- */

let inFlight = 0
const waiters = []

async function acquireSlot() {
  if (inFlight < LIMITS.maxConcurrent) {
    inFlight += 1
    return
  }
  await new Promise((resolve) => waiters.push(resolve))
  inFlight += 1
}

function releaseSlot() {
  inFlight -= 1
  const next = waiters.shift()
  if (next) next()
}

/* -------------------------------------------------------------------------- */
/* Process helpers                                                             */
/* -------------------------------------------------------------------------- */

function runProcess(command, args, options = {}) {
  const { cwd, input = '', timeoutMs = 10_000 } = options

  return new Promise((resolve) => {
    let child
    try {
      child = spawn(command, args, {
        cwd,
        stdio: ['pipe', 'pipe', 'pipe'],
        env: { ...process.env, CLASSPATH: cwd },
        windowsHide: true,
      })
    } catch (error) {
      resolve({ status: -1, stdout: '', stderr: String(error?.message ?? error), timedOut: false })
      return
    }

    let stdout = ''
    let stderr = ''
    let timedOut = false

    const cap = LIMITS.maxOutputChars
    child.stdout.on('data', (chunk) => {
      if (stdout.length < cap) stdout += chunk.toString()
    })
    child.stderr.on('data', (chunk) => {
      if (stderr.length < cap) stderr += chunk.toString()
    })

    const timer = setTimeout(() => {
      timedOut = true
      child.kill('SIGKILL')
    }, timeoutMs)

    child.on('error', (error) => {
      clearTimeout(timer)
      resolve({ status: -1, stdout, stderr: stderr || String(error?.message ?? error), timedOut })
    })

    child.on('close', (code) => {
      clearTimeout(timer)
      resolve({ status: code ?? -1, stdout, stderr, timedOut })
    })

    if (input) {
      child.stdin.write(input)
    }
    child.stdin.end()
  })
}

/* -------------------------------------------------------------------------- */
/* Validation                                                                  */
/* -------------------------------------------------------------------------- */

/**
 * Checks that the source looks like a runnable Java program.
 *
 * @returns {string|null} an error message, or null when the source is fine
 */
export function validateSource(source) {
  if (typeof source !== 'string' || source.trim().length === 0) {
    return 'The code is empty.'
  }
  if (Buffer.byteLength(source, 'utf8') > LIMITS.maxSourceBytes) {
    return `The code is too large (limit ${Math.round(LIMITS.maxSourceBytes / 1024)} kB).`
  }
  if (!/\bclass\s+\w+/.test(source)) {
    return 'The code does not declare a class.'
  }
  if (!/\bstatic\s+(?:public\s+)?void\s+main\s*\(/.test(source)) {
    return 'The code does not declare a main(String[] args) method.'
  }
  return null
}

/* -------------------------------------------------------------------------- */
/* Compile and run                                                             */
/* -------------------------------------------------------------------------- */

/**
 * Compiles a Java source and runs it.
 *
 * @returns {Promise<{status: string, stdout: string, stderr: string,
 *   compileOutput: string, durationMs: number}>}
 */
export async function compileAndRun(source, stdin = '') {
  const started = Date.now()
  const jdk = findJdk()
  if (!jdk) {
    return {
      status: 'Compile Error',
      stdout: '',
      stderr: '',
      compileOutput:
        'No JDK was found on this server. Install a JDK 17+ or set JAVA_HOME to a valid path.',
      durationMs: 0,
    }
  }

  const dir = mkdtempSync(join(tmpdir(), 'dsa-run-'))

  try {
    writeFileSync(join(dir, 'Main.java'), source, 'utf8')

    const compile = await runProcess(jdk.javac, ['-nowarn', '-encoding', 'UTF-8', 'Main.java'], {
      cwd: dir,
      timeoutMs: LIMITS.compileTimeoutMs,
    })

    if (compile.status !== 0) {
      return {
        status: compile.timedOut ? 'Time Limit Exceeded' : 'Compile Error',
        stdout: '',
        stderr: '',
        compileOutput: compile.stderr || compile.stdout || 'Compilation failed.',
        durationMs: Date.now() - started,
      }
    }

    const run = await runProcess(
      jdk.java,
      [`-Xmx${LIMITS.memoryMb}m`, '-XX:+UseSerialGC', '-Dfile.encoding=UTF-8', '-cp', '.', 'Main'],
      { cwd: dir, input: stdin, timeoutMs: LIMITS.runTimeoutMs },
    )

    if (run.timedOut) {
      return {
        status: 'Time Limit Exceeded',
        stdout: run.stdout,
        stderr: run.stderr,
        compileOutput: '',
        durationMs: Date.now() - started,
      }
    }

    if (run.status !== 0) {
      return {
        status: 'Runtime Error',
        stdout: run.stdout,
        stderr: run.stderr || `The program exited with code ${run.status}.`,
        compileOutput: '',
        durationMs: Date.now() - started,
      }
    }

    return {
      status: 'Accepted',
      stdout: run.stdout,
      stderr: run.stderr,
      compileOutput: '',
      durationMs: Date.now() - started,
    }
  } finally {
    rmSync(dir, { recursive: true, force: true })
  }
}

/* -------------------------------------------------------------------------- */
/* Comparison                                                                  */
/* -------------------------------------------------------------------------- */

/** Normalises output for comparison: line endings, trailing whitespace, blank lines. */
export function normaliseOutput(text) {
  return String(text ?? '')
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map((line) => line.replace(/\s+$/, ''))
    .join('\n')
    .replace(/\n+$/, '')
    .trim()
}

export function outputsMatch(actual, expected) {
  return normaliseOutput(actual) === normaliseOutput(expected)
}

/**
 * A line-by-line diff between the expected and the actual output.
 *
 * @returns {Array<{type: 'equal'|'diff'|'missing'|'extra', expected: string|null, actual: string|null, line: number}>}
 */
export function diffOutput(expected, actual) {
  const a = normaliseOutput(expected).split('\n')
  const b = normaliseOutput(actual).split('\n')

  // Longest common subsequence table — the outputs are short, so O(n*m) is fine.
  const n = a.length
  const m = b.length
  const lcs = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      lcs[i][j] = a[i] === b[j] ? lcs[i + 1][j + 1] + 1 : Math.max(lcs[i + 1][j], lcs[i][j + 1])
    }
  }

  const rows = []
  let i = 0
  let j = 0
  let line = 1
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      rows.push({ type: 'equal', expected: a[i], actual: b[j], line })
      i++
      j++
      line++
    } else if (lcs[i + 1][j] >= lcs[i][j + 1]) {
      rows.push({ type: 'missing', expected: a[i], actual: null, line })
      i++
      line++
    } else {
      rows.push({ type: 'extra', expected: null, actual: b[j], line })
      j++
    }
  }
  while (i < n) {
    rows.push({ type: 'missing', expected: a[i], actual: null, line })
    i++
    line++
  }
  while (j < m) {
    rows.push({ type: 'extra', expected: null, actual: b[j], line })
    j++
  }
  return rows
}

/* -------------------------------------------------------------------------- */
/* Judging a submission                                                        */
/* -------------------------------------------------------------------------- */

/**
 * Judges a submission against a set of cases.
 *
 * @param {object} options
 * @param {string} options.source            the user's Java code
 * @param {Array}  options.cases             [{ name, stdin, expected? }]
 * @param {string} [options.referenceSource] the reference solution, used for
 *                                            differential checking
 */
export async function judge({ source, cases = [], referenceSource = null }) {
  await acquireSlot()
  try {
    const invalid = validateSource(source)
    if (invalid) {
      return {
        status: 'Compile Error',
        stdout: '',
        stderr: '',
        compileOutput: invalid,
        durationMs: 0,
        cases: [],
      }
    }

    const results = []
    let overall = 'Accepted'
    let firstOutput = null
    let firstCompileOutput = ''

    for (const [index, testCase] of cases.entries()) {
      const run = await compileAndRun(source, testCase.stdin ?? '')

      if (index === 0) {
        firstOutput = run.stdout
        firstCompileOutput = run.compileOutput
      }

      if (run.status !== 'Accepted') {
        overall = run.status
        results.push({
          name: testCase.name ?? `case ${index + 1}`,
          stdin: testCase.stdin ?? '',
          passed: false,
          expected: testCase.expected ?? null,
          actual: run.stdout,
          status: run.status,
          stderr: run.stderr,
          compileOutput: run.compileOutput,
          diff: null,
        })
        break
      }

      let expected = testCase.expected ?? null
      let basis = 'expected'

      // No recorded expected output? Compare against the reference solution instead.
      if (expected === null && referenceSource) {
        const reference = await compileAndRun(referenceSource, testCase.stdin ?? '')
        if (reference.status === 'Accepted') {
          expected = reference.stdout
          basis = 'reference'
        }
      }

      const passed = expected === null ? true : outputsMatch(run.stdout, expected)

      if (!passed && overall === 'Accepted') {
        overall = 'Wrong Answer'
      }

      results.push({
        name: testCase.name ?? `case ${index + 1}`,
        stdin: testCase.stdin ?? '',
        passed,
        expected,
        actual: run.stdout,
        status: run.status,
        basis: expected === null ? 'none' : basis,
        stderr: run.stderr,
        compileOutput: '',
        diff: passed ? null : diffOutput(expected ?? '', run.stdout),
      })

      if (!passed) {
        // Keep going so the user sees every failing case.
        continue
      }
    }

    return {
      status: overall,
      stdout: firstOutput ?? '',
      stderr: '',
      compileOutput: firstCompileOutput,
      durationMs: results.reduce((sum, r) => sum + (r.durationMs ?? 0), 0),
      cases: results,
    }
  } finally {
    releaseSlot()
  }
}

/**
 * Loads the reference solution for a problem from the generated data.
 *
 * @param {string} problemId e.g. `arrays.TwoSum`
 */
export function loadReferenceSource(problemId, dataDir) {
  if (!problemId || !/^[\w.]+$/.test(problemId)) return null
  const file = join(dataDir, 'problems', `${problemId}.json`)
  if (!existsSync(file)) return null
  try {
    const detail = JSON.parse(readFileSync(file, 'utf8'))
    return detail.judgeSource ?? null
  } catch {
    return null
  }
}
